INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001660011','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001660011","revision":1,"targetId":"80000000-0000-4000-8000-000000016601","prompt":"Ein Eigentümer überlässt seine Wohnung gegen monatliche Miete an eine Familie. Welche Tätigkeit übt er aus?","instruction":{"en":"Read the German situation and select the single correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"He remains the owner and receives rent.","de":"Er bleibt Eigentümer und bekommt Miete."},"options":[{"id":"0","text":"Vermietung"},{"id":"1","text":"Versicherung"},{"id":"2","text":"Verlegung"},{"id":"3","text":"Verkauf"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Vermietung is the act of renting property to someone.","de":"Vermietung bedeutet, eine Immobilie gegen Miete zu überlassen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Er betreibt die Vermietung der Wohnung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2554 (4943273c61646a014b382564bc0d61c7be9e711f78ba7a9e1ad75f7e002288a7), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
